effect.shader:
void main() {
    float size = max(ledSize, 2.0);
    vec2 grid = acResolution / size;
    vec2 cell = floor(acScreenNorm * grid);
    vec2 local = fract(acScreenNorm * grid);

    // A cor do LED vem do centro da célula: um LED tem uma cor só.
    vec4 source = texture(inputImg, clamp((cell + 0.5) / grid, 0.0, 1.0));

    vec3 emitted = source.rgb;
    if (rgbSubpixels) {
        // Cada terço horizontal da célula acende um canal. É como um telão de
        // verdade funciona, e de longe o olho volta a somar as três cores.
        float third = floor(local.x * 3.0);
        vec3 pick = vec3(
            third < 0.5 ? 1.0 : 0.0,
            (third >= 0.5 && third < 1.5) ? 1.0 : 0.0,
            third >= 1.5 ? 1.0 : 0.0
        );
        emitted = source.rgb * pick * 3.0;
    }

    // O vão. `roundLeds` troca a distância de Chebyshev (quadrado) pela
    // euclidiana (círculo) — a mesma conta, outra norma.
    vec2 fromCentre = abs(local - 0.5) * 2.0;
    float distanceToEdge = roundLeds ? length(fromCentre) : max(fromCentre.x, fromCentre.y);
    float lit = 1.0 - smoothstep(1.0 - gap - 0.08, 1.0 - gap, distanceToEdge);

    // Brilho estoura o vão: um LED muito aceso vaza para o vizinho, e sem isso
    // a imagem clara fica com a mesma cara da escura.
    float luma = dot(source.rgb, vec3(0.299, 0.587, 0.114));
    lit = clamp(lit + luma * glowF * (1.0 - lit), 0.0, 1.0);

    vec3 result = mix(panelColor.rgb, clamp(emitted, 0.0, 1.0), lit);
    fragColor = vec4(result, source.a);
}
